library.sqlite.sql:
BEGIN TRANSACTION;
CREATE TABLE actions(id INTEGER PRIMARY KEY AUTOINCREMENT,label TEXT NOT NULL,before_json TEXT NOT NULL,ts TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,undone INTEGER NOT NULL DEFAULT 0);
CREATE TABLE asked(uuid TEXT NOT NULL,entity TEXT NOT NULL,kind TEXT NOT NULL,
 answer TEXT NOT NULL CHECK(answer IN ('yes','no','later')),action_id INTEGER,asked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(uuid,entity));
CREATE TABLE assertions(uuid TEXT NOT NULL,entity TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('confirmed','rejected')),origin TEXT NOT NULL,PRIMARY KEY(uuid,entity));
CREATE TABLE assets(uuid TEXT PRIMARY KEY,filename TEXT,src_path TEXT,width INTEGER,height INTEGER,added_at TEXT,src_kind TEXT);
CREATE TABLE audit_sample(uuid TEXT PRIMARY KEY,entity TEXT NOT NULL,stratum TEXT NOT NULL,
 solo INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auto_rules(uuid TEXT PRIMARY KEY,kind TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE backend_effects(
    id INTEGER PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',
    error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "candidates" (uuid TEXT NOT NULL,entity TEXT NOT NULL,source TEXT NOT NULL,score REAL NOT NULL,PRIMARY KEY(uuid,entity,source)) WITHOUT ROWID;
CREATE TABLE cluster_info(cid INTEGER PRIMARY KEY,size INTEGER NOT NULL,near INTEGER,near_dist REAL,built_at TEXT NOT NULL,
 near_kind TEXT,traits TEXT);
CREATE TABLE clusters(uuid TEXT PRIMARY KEY,cid INTEGER NOT NULL);
CREATE TABLE curation(uuid TEXT PRIMARY KEY,status TEXT NOT NULL CHECK(status IN ('included','excluded')),
 origin TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE deferred(uuid TEXT PRIMARY KEY);
CREATE TABLE display_names(
 kind TEXT NOT NULL, key TEXT NOT NULL, lang TEXT NOT NULL, source TEXT NOT NULL, value TEXT NOT NULL,
 PRIMARY KEY(kind,key,lang,source,value));
CREATE TABLE duplicates(uuid TEXT PRIMARY KEY,grp TEXT NOT NULL,size INTEGER NOT NULL,pos INTEGER NOT NULL,grp_added TEXT NOT NULL,
 rep INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE entities(id TEXT PRIMARY KEY,name TEXT NOT NULL,work TEXT NOT NULL DEFAULT '',external_key TEXT UNIQUE, variant TEXT NOT NULL DEFAULT '', parent_id TEXT REFERENCES entities(id), tag TEXT, merged_into TEXT REFERENCES entities(id), kind TEXT NOT NULL DEFAULT '', artist TEXT NOT NULL DEFAULT '', label_only INTEGER NOT NULL DEFAULT 0, mascot INTEGER NOT NULL DEFAULT 0, mascot_origin TEXT, work_id TEXT REFERENCES entities(id), original INTEGER NOT NULL DEFAULT 0);
CREATE TABLE excluded(uuid TEXT PRIMARY KEY,reason TEXT NOT NULL,origin TEXT NOT NULL);
CREATE TABLE "family_evidence" (uuid TEXT NOT NULL,entity TEXT NOT NULL,sources TEXT NOT NULL,score REAL NOT NULL,
 source_count INTEGER NOT NULL,ccip_only INTEGER NOT NULL,wd REAL,ccip REAL,rank INTEGER NOT NULL,PRIMARY KEY(entity,uuid)) WITHOUT ROWID;
CREATE TABLE identity_anchor_decisions(entity TEXT NOT NULL,reference TEXT NOT NULL,
 decision TEXT NOT NULL CHECK(decision IN ('exclude','restore')),reason TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(entity,reference));
CREATE TABLE identity_anchor_history(id INTEGER PRIMARY KEY,entity TEXT NOT NULL,reference TEXT NOT NULL,
 decision TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE identity_baseline(
 id TEXT PRIMARY KEY,parent_id TEXT,variant TEXT,kind TEXT,merged_into TEXT);
CREATE TABLE identity_canonical(entity TEXT PRIMARY KEY,canonical TEXT NOT NULL);
CREATE TABLE identity_decision_evidence(decision_id INTEGER NOT NULL,fingerprint TEXT NOT NULL,
 PRIMARY KEY(decision_id,fingerprint));
CREATE TABLE identity_decisions(
 id INTEGER PRIMARY KEY,relation_id INTEGER NOT NULL REFERENCES identity_relations(id),
 previous_status TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE identity_evidence(
 relation_id INTEGER NOT NULL REFERENCES identity_relations(id),fingerprint TEXT NOT NULL,
 source TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(relation_id,fingerprint));
CREATE TABLE identity_pairs(a TEXT NOT NULL,b TEXT NOT NULL,original_distance REAL,
 distance REAL,diagnosis TEXT NOT NULL,bank_version TEXT NOT NULL,evidence_json TEXT NOT NULL,PRIMARY KEY(a,b));
CREATE TABLE identity_relations(
 id INTEGER PRIMARY KEY,a TEXT NOT NULL REFERENCES entities(id),b TEXT NOT NULL REFERENCES entities(id),
 kind TEXT NOT NULL CHECK(kind IN ('duplicate_of','form_of','different_from')),
 status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','accepted','rejected')),
 UNIQUE(a,b,kind),CHECK(a<>b));
CREATE TABLE identity_scopes(uuid TEXT NOT NULL,entity TEXT NOT NULL,members_json TEXT NOT NULL,
 PRIMARY KEY(uuid,entity));
CREATE TABLE identity_suspended(uuid TEXT NOT NULL,entity TEXT NOT NULL,reason TEXT NOT NULL,
 options_json TEXT NOT NULL,PRIMARY KEY(uuid,entity));
CREATE TABLE identity_uncertain(uuid TEXT PRIMARY KEY,options_json TEXT NOT NULL,reason TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE image_sigs(uuid TEXT PRIMARY KEY,ratio REAL,grid BLOB,ok INTEGER NOT NULL);
CREATE TABLE imported(uuid TEXT NOT NULL,value TEXT NOT NULL,PRIMARY KEY(uuid,value));
CREATE TABLE lead_assets(uuid TEXT PRIMARY KEY);
CREATE TABLE learn_state(entity TEXT PRIMARY KEY,signature TEXT NOT NULL,learned_at TEXT NOT NULL);
CREATE TABLE links(system TEXT NOT NULL,key TEXT NOT NULL,entity_id TEXT NOT NULL REFERENCES entities(id),
 current INTEGER NOT NULL DEFAULT 1,source TEXT NOT NULL,added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(system,key));
CREATE TABLE memberships(uuid TEXT NOT NULL,entity TEXT NOT NULL,status TEXT NOT NULL,origin TEXT,
 sources TEXT NOT NULL,score REAL,source_count INTEGER NOT NULL,ccip_only INTEGER NOT NULL,skey TEXT NOT NULL,
 PRIMARY KEY(entity,uuid)) WITHOUT ROWID;
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE name_aliases(kind TEXT NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(kind,key,value));
CREATE TABLE name_cache(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE name_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE names(entity_id TEXT NOT NULL REFERENCES entities(id),lang TEXT NOT NULL DEFAULT '' CHECK(lang IN ('','zh','ja','en')),
 value TEXT NOT NULL,source TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('display','alias')),preferred INTEGER NOT NULL DEFAULT 0,
 position INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(entity_id,role,lang,source,value));
CREATE TABLE prefs(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE proto_claims(uuid TEXT NOT NULL,entity TEXT NOT NULL,score REAL NOT NULL,PRIMARY KEY(entity,uuid));
CREATE TABLE prototypes(entity TEXT NOT NULL,k INTEGER NOT NULL,vec BLOB NOT NULL,threshold REAL NOT NULL,
 seeds INTEGER NOT NULL,hint REAL NOT NULL,PRIMARY KEY(entity,k));
CREATE TABLE relations(a TEXT NOT NULL,b TEXT NOT NULL,kind TEXT NOT NULL,changed REAL,note TEXT NOT NULL DEFAULT '',
 checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(a,b));
CREATE TABLE reviews(entity TEXT NOT NULL,reviewed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,action_id INTEGER PRIMARY KEY);
CREATE TABLE similar_groups(uuid TEXT PRIMARY KEY,gid INTEGER NOT NULL);
CREATE TABLE single_assets(uuid TEXT PRIMARY KEY);
CREATE TABLE sync_added(uuid TEXT PRIMARY KEY,run_id INTEGER NOT NULL);
CREATE TABLE sync_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 finished_at TEXT,status TEXT NOT NULL,found INTEGER NOT NULL DEFAULT 0,removed INTEGER NOT NULL DEFAULT 0,
 imported INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,sources TEXT,message TEXT);
CREATE TABLE tag_memberships(uuid TEXT NOT NULL,entity TEXT NOT NULL,status TEXT NOT NULL,origin TEXT,
 sources TEXT NOT NULL,score REAL,source_count INTEGER NOT NULL,ccip_only INTEGER NOT NULL,skey TEXT NOT NULL,
 PRIMARY KEY(entity,uuid)) WITHOUT ROWID;
CREATE TABLE "term_active_evidence"(
 asset_id INTEGER NOT NULL REFERENCES term_assets(id),
 source TEXT NOT NULL,
 method TEXT NOT NULL,
 set_id INTEGER NOT NULL REFERENCES "term_evidence_sets"(id),
 PRIMARY KEY(asset_id,source,method)) WITHOUT ROWID;
CREATE TABLE term_assets(
 id INTEGER PRIMARY KEY,
 namespace TEXT NOT NULL CHECK(length(namespace) BETWEEN 1 AND 32),
 key TEXT NOT NULL CHECK(length(key) BETWEEN 1 AND 256),
 md5 TEXT CHECK(md5 IS NULL OR length(md5)=32),
 added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 removed_at TEXT,
 UNIQUE(namespace,key));
CREATE TABLE term_batches(
 id INTEGER PRIMARY KEY,
 kind TEXT NOT NULL CHECK(kind IN ('baseline','album','undo_audit','migration')),
 anchor INTEGER NOT NULL CHECK(anchor>=0),
 label TEXT NOT NULL DEFAULT '',
 data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data) AND json_type(data)='object'),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE term_evidence(
 id INTEGER PRIMARY KEY,
 asset_id INTEGER REFERENCES term_assets(id),
 term_id INTEGER REFERENCES terms(id),
 relation_id INTEGER REFERENCES term_relations(id),
 source TEXT NOT NULL CHECK(source NOT IN ('user','human','album','legacy','verdict')),
 method TEXT NOT NULL,
 version TEXT NOT NULL,
 score REAL,
 metric TEXT,
 data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data) AND json_type(data)='object'),
 fingerprint BLOB NOT NULL CHECK(length(fingerprint)=16),
 package_id INTEGER REFERENCES term_packages(id),
 observed_at TEXT,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((asset_id IS NOT NULL AND term_id IS NOT NULL AND relation_id IS NULL)
    OR (asset_id IS NULL AND term_id IS NULL AND relation_id IS NOT NULL)),
 CHECK((score IS NULL) = (metric IS NULL)));
CREATE TABLE "term_evidence_set_assets"(
 set_id INTEGER NOT NULL REFERENCES "term_evidence_sets"(id),
 asset_id INTEGER NOT NULL REFERENCES term_assets(id),
 PRIMARY KEY(set_id,asset_id)) WITHOUT ROWID;
CREATE TABLE "term_evidence_set_rows"(
 set_id INTEGER NOT NULL REFERENCES "term_evidence_sets"(id),
 evidence_id INTEGER NOT NULL REFERENCES term_evidence(id),
 PRIMARY KEY(set_id,evidence_id)) WITHOUT ROWID;
CREATE TABLE "term_evidence_sets"(
 id INTEGER PRIMARY KEY,
 producer TEXT NOT NULL CHECK(length(producer) BETWEEN 1 AND 80),
 source TEXT NOT NULL,
 method TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(scope IN ('all','assets')),
 package_id INTEGER REFERENCES term_packages(id),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((source='provenance' AND method='*') OR source||'.'||method IN ('wd.wd_character','ccip_index.char_ext')));
CREATE TABLE term_identity_baseline(
 seq INTEGER PRIMARY KEY,
 id TEXT NOT NULL UNIQUE,
 parent_id TEXT,
 variant TEXT,
 kind TEXT,
 merged_into TEXT);
CREATE TABLE term_key_aliases(
 kind TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, position INTEGER NOT NULL,
 PRIMARY KEY(kind,key,value)) WITHOUT ROWID;
CREATE TABLE term_key_names(
 kind TEXT NOT NULL, key TEXT NOT NULL, lang TEXT NOT NULL, source TEXT NOT NULL, value TEXT NOT NULL,
 PRIMARY KEY(kind,key,lang,source,value)) WITHOUT ROWID;
CREATE TABLE term_legacy_ids(
 kind TEXT NOT NULL CHECK(kind IN ('relation','decision')),
 legacy_id INTEGER NOT NULL,
 core_id INTEGER NOT NULL,
 PRIMARY KEY(kind,legacy_id),
 UNIQUE(kind,core_id)) WITHOUT ROWID;
CREATE TABLE term_links(
 system TEXT NOT NULL CHECK(length(system) BETWEEN 1 AND 32),
 key TEXT NOT NULL CHECK(length(key) BETWEEN 1 AND 256),
 term_id INTEGER NOT NULL REFERENCES terms(id),
 url TEXT NOT NULL DEFAULT '',
 source TEXT NOT NULL,
 current INTEGER NOT NULL DEFAULT 1 CHECK(current IN (0,1)),
 added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(system,key));
CREATE TABLE term_name_choice(
 kind TEXT NOT NULL, key TEXT NOT NULL,
 name TEXT NOT NULL, name_source TEXT NOT NULL, zh TEXT, ja TEXT, en TEXT,
 PRIMARY KEY(kind, key)) WITHOUT ROWID;
CREATE TABLE term_name_display(
 entity TEXT NOT NULL, skin_only INTEGER NOT NULL CHECK(skin_only IN (0,1)),
 name TEXT NOT NULL, name_source TEXT NOT NULL, zh TEXT, ja TEXT, en TEXT, tag TEXT NOT NULL,
 PRIMARY KEY(entity, skin_only)) WITHOUT ROWID;
CREATE TABLE term_names(
 term_id INTEGER NOT NULL REFERENCES terms(id),
 lang TEXT NOT NULL DEFAULT '' CHECK(lang IN ('','zh','ja','en')),
 value TEXT NOT NULL CHECK(length(value) BETWEEN 1 AND 200),
 role TEXT NOT NULL CHECK(role IN ('display','alias')),
 source TEXT NOT NULL,
 preferred INTEGER NOT NULL DEFAULT 0 CHECK(preferred IN (0,1)),
 position INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(term_id,role,lang,source,value));
CREATE TABLE term_packages(
 id INTEGER PRIMARY KEY,
 fingerprint TEXT NOT NULL UNIQUE CHECK(length(fingerprint)=64),
 producer TEXT NOT NULL,
 producer_version TEXT NOT NULL,
 library_id TEXT NOT NULL,
 manifest TEXT NOT NULL CHECK(json_valid(manifest)),
 evidence_count INTEGER NOT NULL,
 skipped_count INTEGER NOT NULL DEFAULT 0,
 imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE term_projection(
 asset_id INTEGER NOT NULL REFERENCES term_assets(id),
 term_id INTEGER NOT NULL REFERENCES terms(id),
 state TEXT NOT NULL CHECK(state IN ('confirmed','machine','maybe','rejected')),
 score REAL,
 sources TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(asset_id,term_id)) WITHOUT ROWID;
CREATE TABLE term_relations(
 id INTEGER PRIMARY KEY,
 a INTEGER NOT NULL REFERENCES terms(id),
 b INTEGER NOT NULL REFERENCES terms(id),
 kind TEXT NOT NULL CHECK(kind IN ('contains','same_as','different_from','excludes')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(a,b,kind),
 CHECK(a<>b),
 CHECK(kind IN ('contains','same_as') OR a<b));
CREATE TABLE term_tree(
 term_id INTEGER PRIMARY KEY REFERENCES terms(id),
 parent_id TEXT,
 merged_into TEXT,
 work_id TEXT,
 work_text TEXT NOT NULL DEFAULT '',
 review_status TEXT,
 review_note TEXT,
 parent_locked INTEGER,
 CHECK((review_status IS NULL)=(review_note IS NULL) AND (review_status IS NULL)=(parent_locked IS NULL)));
CREATE TABLE "term_verdicts"(
 id INTEGER PRIMARY KEY,
 action_id INTEGER REFERENCES actions(id),
 asset_id INTEGER REFERENCES term_assets(id),
 term_id INTEGER REFERENCES terms(id),
 relation_id INTEGER REFERENCES term_relations(id),
 verdict TEXT NOT NULL CHECK(verdict IN ('yes','no','clear')),
 origin TEXT NOT NULL CHECK(origin IN ('user','album','legacy')),
 reason TEXT NOT NULL DEFAULT '',
 reviewed TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(reviewed) AND json_type(reviewed)='array'),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 batch_id INTEGER REFERENCES term_batches(id),
 anchor INTEGER NOT NULL,
 via TEXT NOT NULL DEFAULT '' CHECK(length(via)<=40),
 CHECK((action_id IS NULL)<>(batch_id IS NULL)),
 CHECK(action_id IS NULL OR anchor=action_id),
 CHECK((asset_id IS NOT NULL AND term_id IS NOT NULL AND relation_id IS NULL)
    OR (asset_id IS NULL AND term_id IS NULL AND relation_id IS NOT NULL)));
CREATE TABLE terms(
 id INTEGER PRIMARY KEY,
 key TEXT NOT NULL UNIQUE CHECK(length(key) BETWEEN 1 AND 128),
 kind TEXT NOT NULL,
 origin TEXT NOT NULL CHECK(length(origin) BETWEEN 1 AND 80),
 attrs TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(attrs) AND json_type(attrs)='object'),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE weak_claims(uuid TEXT NOT NULL,entity TEXT NOT NULL,source TEXT NOT NULL,score REAL NOT NULL,
 PRIMARY KEY(entity,uuid,source));
CREATE TABLE work_review(entity_id TEXT PRIMARY KEY REFERENCES entities(id),
        status TEXT NOT NULL DEFAULT 'pending',note TEXT NOT NULL DEFAULT '',parent_locked INTEGER NOT NULL DEFAULT 0);
